function renderBanquet(){
 const select=document.getElementById('banquetVenue');const outfit=document.getElementById('banquetCostume');if(!select||!outfit)return;
 select.value=state.banquetVenue;outfit.value=state.banquetCostume;
 const v=currentBanquet(),n=clampInt(state.travelers,1,40,10),extra=costumePrice(),panel=document.getElementById('banquetDetail');
 if(!v){panel.innerHTML='<div class="banquet-off">Chưa chọn Cung Yến. Lịch trình & ngân sách quay về phương án gốc. Bạn có thể chọn một trong ba thành phố ở trên.</div>';return;}
 panel.innerHTML=`<div class="banquet-detail"><div><div class="micro">NGÀY ${v.day} · ${esc(v.city)} · THAY CHO BỮA TỐI THƯỜNG</div><h3>${esc(v.name)}</h3><p>${esc(v.address)}</p><p>${esc(v.approxSession)}</p>${v.id==='sz'&&state.startDate&&new Date(state.startDate+'T12:00:00').getDay()===6?'<p style="color:#b04c31"><b>⚠ Ngày 3 rơi vào thứ Hai: Ngự Yến Tô Châu công bố nghỉ thứ Hai. Hãy đổi nơi dự tiệc hoặc ngày đi.</b></p>':''}<p>${esc(v.detail)}</p><p><b>Lưu ý giá/giờ:</b> ${esc(v.note)}</p><p><b>Đoàn ${n} người:</b> cần hỏi xem có cùng khu ghế, chỗ dành cho người lớn tuổi, chính sách trẻ em và nơi xe lớn đón/trả.</p><div class="banquet-links"><a href="${v.mapUrl}" target="_blank" rel="noopener noreferrer">↗ Bản đồ Amap</a><a href="${v.booking}" target="_blank" rel="noopener noreferrer">↗ Xem vé / liên hệ</a><a href="${v.source}" target="_blank" rel="noopener noreferrer">Nguồn tham khảo</a><button type="button" id="banquetGoDay">Xem lịch ngày ${v.day} →</button></div></div><div><strong>${formatExactCny(v.low+extra)}–${formatExactCny(v.high+extra)} ¥</strong><div class="micro">/ người · gồm dự trù trang phục chọn</div><div class="micro" style="margin-top:7px">Đoàn: ${formatExactCny((v.low+extra)*n)}–${formatExactCny((v.high+extra)*n)} ¥</div><div class="micro">Chưa phải giá / vé được xác nhận</div></div></div>`;
 document.getElementById('banquetGoDay').addEventListener('click',()=>{state.day=v.day;save();renderDay();dayCards();document.getElementById('daySwitcher').scrollIntoView({behavior:'smooth',block:'start'})});
}
