// Extrapolate proportionally for a 7-day request until an operator quotes the full 7-day route.
const vehicleRange7=(v)=>({low:Math.round(v.low*7/6/100)*100,high:Math.round(v.high*7/6/100)*100});
const transferLegs=[
{from:'Thượng Hải → Tô Châu',duration:'~1,5–2,5 giờ',detail:'Xe đón khách sạn Thượng Hải, trả tại Gusu; cộng thời gian nếu kẹt cao tốc.'},
{from:'Tô Châu → Ô Trấn',duration:'~1–2 giờ',detail:'Đưa tới trung tâm du khách Tây Sách; xe lớn không vào nội khu.'},
{from:'Ô Trấn → Hồ Thanh Sơn → Hàng Châu',duration:'~1,5–2,5h + ~1–1,5h',detail:'Hai chặng xe riêng qua rừng nước 青山湖水上森林 tại Lâm An, chưa bao gồm ~2–3h tham quan; có thể phát sinh chi phí xe/đỗ so với tuyến đi thẳng.'},
{from:'Hàng Châu → sân bay Thượng Hải',duration:'~3–4,5 giờ',detail:'Đặc biệt chú ý sân bay PVG, giờ cao điểm; nên bay chiều muộn hoặc tối.'}
];

const checks=[{key:'tickets',name:'Vé & thủ tục',desc:'Nên hoàn tất trước khi đi',items:['Xác minh yêu cầu visa / nhập cảnh theo hộ chiếu','Hộ chiếu còn hiệu lực và bảo hiểm nếu cần','Đặt và kiểm tra vé máy bay, số hiệu sân bay, giờ hạ cánh; xác nhận ngày 1 có đủ thời gian citywalk Thượng Hải','Nếu dùng phương án tàu: đặt vé 12306 sau khi lịch mở bán','Liên hệ khách sạn xin giá theo đoàn, loại giường và số phòng Twin','Kiểm tra vé Tây Sách và điều kiện combo lưu trú','Đặt khung giờ Linh Ẩn nếu lựa chọn tham quan','Nếu có Cung Yến: giữ ghế cùng khu cho cả đoàn và xác nhận giờ diễn / suất ăn / trang phục']},{key:'essentials',name:'Hành lý cá nhân',desc:'Tùy thời tiết và loại chuyến đi',items:['Trang phục đủ 7 ngày và giày đi bộ thoải mái','Áo khoác / áo mỏng theo thời tiết thực tế','Ô gấp, áo mưa nhẹ nếu có dự báo mưa','Thuốc cá nhân và vật dụng vệ sinh','Điện thoại, cáp sạc, pin dự phòng đúng quy định vận chuyển','Bản sao điện tử hộ chiếu và booking']},{key:'shared',name:'Dùng chung & thanh toán',desc:'Những thứ nhóm có thể chuẩn bị chung',items:['Cài và thử thanh toán Alipay / WeChat Pay','Cài Amap 高德地图, lưu địa chỉ tiếng Trung','Chuẩn bị eSIM / roaming / giải pháp Internet','Lưu địa chỉ khách sạn, điểm tập trung xe và số điện thoại tài xế','Xác nhận loại xe phù hợp số khách + vali, phí thuê trọn 7 ngày, bao gồm đi vòng qua Hồ Thanh Sơn ngày 5']},{key:'final',name:'Kiểm tra trước giờ khởi hành',desc:'Đối chiếu lần cuối khi đã có ngày đi',items:['Kiểm tra biển số xe, tài xế, lịch đón và phí phát sinh (hoặc vé tàu nếu chọn)','Kiểm tra trạng thái mở cửa Hồ Thanh Sơn – khu Water Forest (青山湖水上森林), vé và dịch vụ thuyền theo mực nước', 'Kiểm tra giờ mở cửa và thông báo từ thắng cảnh','Xác nhận giờ mở cửa Bảo tàng Trà và giá trải nghiệm Long Tỉnh (nếu tham gia)','Kiểm tra thời tiết 3–5 ngày trước chuyến đi','Kiểm tra ngày 7: thời gian lái xe Hàng Châu → sân bay PVG/SHA và buffer check-in','Tải về / chụp thông tin quan trọng để xem khi mất mạng']}];
const pages=[{id:'overview',name:'Tổng quan',ic:'home'},{id:'itinerary',name:'Lịch trình',ic:'calendar'},{id:'hotels',name:'Khách sạn',ic:'hotel'},{id:'transport',name:'Thuê xe',ic:'train'},{id:'map',name:'Bản đồ',ic:'map'},{id:'budget',name:'Chi phí',ic:'wallet'},{id:'prep',name:'Chuẩn bị',ic:'check'}];
const storageKey='jiangnan6-travel-pocketbook-v2';
let state={page:'overview',day:1,startDate:'',travelers:10,bags:10,mode:'private',selectedHotels:{sh:'sh-camp',sz:'sz-hie',wz:'wz-tongan',hz:'hz-hie'},checks:{},notes:{},savedSpots:{},banquetVenue:'sh',banquetCostume:'none'};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');state={...state,...saved,selectedHotels:{...state.selectedHotels,...(saved.selectedHotels||{})},savedSpots:{...(saved.savedSpots||{})},banquetVenue:['sh','sz','hz','hz6','none'].includes(saved.banquetVenue)?saved.banquetVenue:'sh',banquetCostume:['none','hair','full'].includes(saved.banquetCostume)?saved.banquetCostume:'none',page:'overview',day:Math.min(7,Math.max(1,Number(saved.day)||1))};}catch(e){}
function save(){try{localStorage.setItem(storageKey,JSON.stringify({...state,page:'overview'}));}catch(e){}}
function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function amap(query,city){return 'https://uri.amap.com/search?keyword='+encodeURIComponent(query)+'&city='+encodeURIComponent(city||'')+'&view=map&src=travel-pocketbook&callnative=1'}
function dateOf(n){if(!state.startDate)return '';const start=new Date(state.startDate+'T12:00:00');if(Number.isNaN(start.getTime()))return '';start.setDate(start.getDate()+n-1);return start.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'})}
function dateRange(){if(!state.startDate)return 'Chưa thiết lập';return dateOf(1)+' – '+dateOf(7)}
function formatCny(n){return (Math.round(n/10)*10).toLocaleString('en-US')}
function notify(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),2400)}
function createNav(){const nav=(mobile)=>pages.map(p=>`<button type="button" class="${mobile?'mobile-button ':'nav-btn '}${state.page===p.id?'active':''}" data-page="${p.id}" aria-label="${p.name}">${icon(p.ic)}<span>${p.name}</span></button>`).join('');document.getElementById('desktopNav').innerHTML=nav(false);document.getElementById('mobileNav').innerHTML=nav(true);document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.page)));}
function show(page){state.page=page;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+page));createNav();if(page==='budget')renderBudget();if(page==='hotels')renderHotels();if(page==='transport')renderTransport();if(page==='prep')renderChecks();window.scrollTo({top:0,behavior:'smooth'});}
function routeRender(){document.getElementById('routeTrack').innerHTML=cities.map(c=>`<div class="route-stop"><div class="route-circle">${icon(c.ic,24)}</div><div class="city">${c.name}</div><div class="time">${c.days}</div></div>`).join('');document.getElementById('datePreview').textContent=dateRange();document.getElementById('overviewGroupSize').textContent=state.travelers+' người / '+Math.ceil(state.travelers/2)+' phòng';}

function scenicEscape(s){return esc(s)}
function scenicImg(k,cls=''){const p=scenicPhotos[k];if(!p)return '';return `<img class="${cls}" loading="lazy" decoding="async" src="${scenicEscape(p.url)}" data-fallback="${scenicEscape(p.fallbackUrl||'')}" alt="Ảnh chụp thật: ${scenicEscape(p.name)}" title="Ảnh: ${scenicEscape(p.author)} · ${scenicEscape(p.license)}" data-credit="${scenicEscape(p.page||'')}" onerror="if(!this.dataset.attempted && this.dataset.fallback){this.dataset.attempted='1';this.src=this.dataset.fallback;}else{this.closest('.scene-media')?.classList.add('image-fallback');this.style.display='none';}">`}
function scenicSource(k,inner='Nguồn ảnh ↗'){const p=scenicPhotos[k];return p?`<a target="_blank" rel="noopener noreferrer" href="${scenicEscape(p.page)}" title="Nguồn: ${scenicEscape(p.author)} · ${scenicEscape(p.license)}">${inner}</a>`:''}
function scenicGalleryRender(n){const keys=scenicDayKeys[n]||[];const node=document.getElementById('scenicGrid');if(!node)return;node.innerHTML=keys.map(k=>{const p=scenicPhotos[k];return `<figure class="scene-tile"><a class="scene-media" href="${scenicEscape(p.page)}" target="_blank" rel="noopener noreferrer" title="Mở ảnh gốc của ${scenicEscape(p.name)}">${scenicImg(k)}<span class="image-wait">Không tải được ảnh; nhấn để xem từ nguồn ↗</span></a><figcaption><strong>${scenicEscape(p.name)}</strong><a href="${scenicEscape(p.page)}" target="_blank" rel="noopener noreferrer">📸 ${scenicEscape(p.author)} · ${scenicEscape(p.license)} ↗</a></figcaption></figure>`}).join('')}
function scenicStopKey(s){const z=(s.q||'')+' '+(s.title||'');if(/青山湖|水上森林/.test(z))return 'qingshan';if(/拙政园/.test(z))return 'garden';if(/平江路/.test(z))return 'pingjiang';if(/山塘/.test(z))return 'shantang';if(/西栅|乌镇/.test(z))return /夜|đêm/i.test(z)?'wuzhen_night':'wuzhen';if(/灵隐|飞来峰/.test(z))return 'lingyin';if(/中国茶叶博物馆/.test(z))return 'extra_hz-tea-museum';if(/龙井/.test(z))return 'longjing';if(/河坊街|南宋御街/.test(z))return 'hefang';if(/西湖/.test(z))return 'westlake';if(/武康/.test(z))return 'wukang_mansion';if(/安福路/.test(z))return 'anfu';if(/豫园/.test(z))return 'yuyuan';if(/南京路|南京东路/.test(z))return 'nanjing';if(/外白渡桥/.test(z))return 'waibaidu';if(/外滩源|圆明园路|Rockbund/.test(z))return 'rockbund';if(/外滩|陆家嘴/.test(z))return 'bund';return null}
function scenicStopMarkup(s){if(!['Chính','Tùy chọn'].includes(s.kind))return '';const k=scenicStopKey(s);if(!k)return '';const p=scenicPhotos[k];return `<figure class="entry-scene">${scenicImg(k)}<div class="scene-bottom"><span>Ảnh chụp thật · ${scenicEscape(p.name)}</span>${scenicSource(k)}</div></figure>`}
function scenicTipKey(p){if(p.imgKey)return p.imgKey;const z=(p.q||'')+' '+(p.title||'');if(/圆明园|Rockbund/.test(z))return 'rockbund';if(/外白渡桥/.test(z))return 'waibaidu';if(/陆家嘴|外滩/.test(z))return 'bund';if(/安福路/.test(z))return 'anfu';if(/武康/.test(z))return 'wukang_mansion';if(/豫园/.test(z))return 'yuyuan';return null}
function extraScenicKey(p){if(!p)return null;const k='extra_'+p.id;return scenicPhotos[k]?k:null}
function extraScenicMarkup(p){const k=extraScenicKey(p);if(!k||!scenicPhotos[k])return '';const s=scenicPhotos[k];return `<div class="extra-photo-block"><a class="extra-card-media scene-media" href="${scenicEscape(s.page)}" target="_blank" rel="noopener noreferrer" title="Mở ảnh chụp thật của ${scenicEscape(s.name)}">${scenicImg(k)}<span class="media-credit">Ảnh thật ↗</span><span class="image-wait">Ảnh đang không tải được · Nhấn xem nguồn gốc ↗</span></a><a class="extra-photo-credit" href="${scenicEscape(s.page)}" target="_blank" rel="noopener noreferrer">Ảnh: ${scenicEscape(s.author)} · ${scenicEscape(s.license)} ↗</a></div>`}
function renderPhotoCredits(){const el=document.getElementById('photoCredits');if(!el)return;el.innerHTML=Object.values(scenicPhotos).map(p=>`<li><a target="_blank" rel="noopener noreferrer" href="${scenicEscape(p.page)}">${scenicEscape(p.name)}</a> — ${scenicEscape(p.author)} · ${scenicEscape(p.license)}</li>`).join('')}

function dayCards(){document.getElementById('overviewDays').innerHTML=days.map(d=>`<article class="day-card" tabindex="0" role="button" aria-label="Mở lịch trình ngày ${d.number}" data-day-open="${d.number}"><div class="day-art" style="background:linear-gradient(128deg,${d.shade},#91bda2)">${scenicImg(scenicLeadKeys[d.number],'real-day-img')}<span class="number">Day ${String(d.number).padStart(2,'0')}</span><span class="symbol">${esc(d.symbol)}</span><span class="place">${esc(d.city)}</span></div><div class="day-card-content"><div class="date">${dateOf(d.number)||'NGÀY '+String(d.number).padStart(2,'0')}</div><h3>${esc(d.short)}</h3><p>${esc(d.description)}</p><div class="day-card-footer"><span>${d.pace} · ${d.stops.length} mốc</span><span class="arrow">→</span></div></div></article>`).join('');document.querySelectorAll('[data-day-open]').forEach(el=>{const fn=()=>{state.day=+el.dataset.dayOpen;save();renderDay();show('itinerary')};el.addEventListener('click',fn);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})});}
function renderDay(){updateBanquetSchedule();updateTravelData();const d=days[state.day-1];const photoPanel=document.getElementById('photoHighlights');const photoItems=d.photoTips||[];photoPanel.hidden=!photoItems.length;document.getElementById('photoSpotGrid').innerHTML=photoItems.map(p=>{const k=scenicTipKey(p);return `<article class="photo-spot">${k?scenicImg(k,'photo-spot-img'):''}<div class="photo-spot-content"><small>${esc(p.label)}</small><strong>${esc(p.title)}</strong><p>${esc(p.desc)}</p><a target="_blank" rel="noopener noreferrer" href="${amap(p.q,'上海')}">${icon('pin',13)} Mở Amap ↗</a></div></article>`}).join('');scenicGalleryRender(d.number);document.getElementById('daySwitcher').innerHTML=days.map(x=>`<button type="button" class="day-tab ${d.number===x.number?'active':''}" data-day="${x.number}"><small>DAY ${String(x.number).padStart(2,'0')} ${dateOf(x.number)?'· '+dateOf(x.number).slice(0,5):''}</small><strong>${esc(x.city)}</strong></button>`).join('');document.querySelectorAll('[data-day]').forEach(b=>b.addEventListener('click',()=>{state.day=+b.dataset.day;save();renderDay()}));document.getElementById('dayStory').classList.add('has-real-image');document.getElementById('dayStory').innerHTML=`${scenicImg(scenicLeadKeys[d.number],'day-scene')}${scenicSource(scenicLeadKeys[d.number],'Ảnh thật · Nguồn ↗').replace('<a ','<a class="day-scene-source" ')}<div class="overline">DAY ${String(d.number).padStart(2,'0')} · ${esc(d.zh)}</div><h2>${esc(d.heading)}</h2><p>${esc(d.summary)}</p><div class="day-tags"><span>${icon('sun',13)} ${esc(d.pace)}</span><span>${d.stops.length} mốc thời gian</span><span>${dateOf(d.number)||'Chưa chọn ngày'}</span></div>`;document.getElementById('stayPanel').innerHTML=stayPanelHTML(d.number);
 document.getElementById('timeline').innerHTML=d.stops.map(s=>`<div class="entry ${s.kind==='Tùy chọn'?'optional':''} ${s.kind==='Cung Yến'?'feast':''}"><div class="entry-hd"><span class="entry-time">${esc(s.t)}</span><span class="tag ${s.kind==='Tùy chọn'?'optional':''}">${esc(s.kind)}</span><span class="tag">${esc(s.duration)}</span></div><h4>${esc(s.title)}</h4>${scenicStopMarkup(s)}<p>${esc(s.detail)}</p><div class="entry-trans">${icon('train',13)} <span>${esc(s.transport)}</span></div><div class="entry-links"><a target="_blank" rel="noopener noreferrer" href="${amap(s.q,s.city)}">${icon('pin',13)} Mở Amap ↗</a>${s.booking?`<a href="${s.booking}" target="_blank" rel="noopener noreferrer">${icon('food',13)} Xem vé Cung Yến ↗</a>`:''}</div></div>`).join('');
 document.getElementById('transportInfo').innerHTML=`<div class="ico-title">${icon('train',16)} Di chuyển</div><p>${esc(d.transport)}</p>${state.mode==='hybrid'&&(d.number===3||d.number===7)?'<a href="https://www.12306.cn/en/" target="_blank" rel="noopener noreferrer">Xem website tàu 12306 ↗</a>':''}`;
 document.getElementById('foodInfo').innerHTML=`<div class="ico-title">${icon('food',16)} Món nên thử</div><ul>${d.food.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>`;
 document.getElementById('alternateInfo').innerHTML=`<div class="ico-title">${icon('alert',16)} Phương án dự phòng</div><p>${esc(d.alt)}</p><p><strong>Đừng quên:</strong> ${esc(d.note)}</p>`;
 const notes=document.getElementById('dayNotes');notes.value=state.notes[d.number]||'';notes.oninput=()=>{state.notes[d.number]=notes.value;save()};renderOtherSpots();renderBanquet();}

function optionalCityKey(){return state.day<=2?'sh':state.day===3?'sz':state.day===4?'wz':'hz'}
function renderOtherSpots(){
 const cityKey=optionalCityKey(), names={sh:'Thượng Hải',sz:'Tô Châu',wz:'Ô Trấn',hz:'Hàng Châu'};
 const all=extraSpots.filter(p=>p.city===cityKey && !['hz-longjing','hz-tea-museum'].includes(p.id));
 const savedCount=all.filter(p=>state.savedSpots[p.id]).length;
 const filtered=all.filter(p=>extraFilter==='all'||(extraFilter==='easy'&&p.easy)||(extraFilter==='saved'&&state.savedSpots[p.id]));
 document.getElementById('extraSpotsTitle').textContent='Địa điểm tham khảo khác · '+names[cityKey];
 document.getElementById('extraSpotSubtitle').textContent=state.day===7?'Ngày 7 ưu tiên ra sân bay. Gợi ý Hàng Châu dưới đây chỉ phù hợp nếu đã chốt chuyến bay rất muộn, đủ thời gian di chuyển và làm thủ tục.':'Dành cho đoàn linh hoạt thay thế hoặc thêm khi còn thời gian; không phải mốc tham quan đã sắp xếp.';
 document.getElementById('extraCount').textContent=all.length+' gợi ý · '+savedCount+' đã lưu';
 document.getElementById('extraFilters').innerHTML=[['all','Tất cả ('+all.length+')'],['easy','Dễ ghép ('+all.filter(p=>p.easy).length+')'],['saved','Đã lưu ('+savedCount+')']].map(([k,label])=>'<button type="button" class="extra-filter '+(extraFilter===k?'active':'')+'" data-extra-filter="'+k+'" aria-pressed="'+(extraFilter===k?'true':'false')+'">'+label+'</button>').join('');
 document.getElementById('extraSpotGrid').innerHTML=filtered.length?filtered.map(p=>{const saved=!!state.savedSpots[p.id];return `<article class="extra-card">${extraScenicMarkup(p)}<div class="extra-card-top"><div class="extra-emoji" aria-hidden="true">${p.emoji}</div><div class="extra-place"><span class="extra-cat">${esc(p.category)}</span><h3>${esc(p.name)}</h3><small>${esc(p.zh)}</small></div></div><p class="extra-summary">${esc(p.blurb)}</p><div class="extra-location">${icon('pin',13)} <span>${esc(p.area)}</span></div><div class="extra-meta"><span class="extra-chip">${icon('sun',11)} ${esc(p.time)}</span><span class="extra-chip ${p.easy?'':'advanced'}">${esc(p.badge)}</span></div><div class="extra-advice"><b>${esc(p.fit)}</b><br>${esc(p.note)}</div><div class="extra-card-actions"><a class="map-link" href="${amap(p.query,p.cityQuery)}" target="_blank" rel="noopener noreferrer">${icon('pin',14)} Mở Amap ↗</a><button type="button" class="extra-save ${saved?'saved':''}" data-extra-save="${p.id}" aria-pressed="${saved?'true':'false'}">${saved?'♥ Đã lưu':'♡ Lưu quan tâm'}</button><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer" title="Nguồn tham khảo về điểm đến">Nguồn ↗</a></div></article>`}).join(''):'<div class="extra-empty">Chưa có gợi ý nào trong bộ lọc này. Nhấn “Tất cả” để xem thêm địa điểm.</div>';
}

function mapRender(){document.getElementById('mapCities').innerHTML=cities.map((c,i)=>`<div class="map-stop"><div class="map-bullet">0${i+1}</div><div><strong>${c.name} <span class="micro">${c.zh}</span></strong><div class="small">${c.days}</div></div><div class="right"><a target="_blank" rel="noopener noreferrer" href="${amap(c.q,c.city)}">Amap ↗</a></div></div>`).join('');const locations=[{name:'Rockbund / Waitanyuan · 外滩源',q:'外滩源 圆明园路',city:'上海'},{name:'Cầu Waibaidu · 外白渡桥',q:'外白渡桥',city:'上海'},{name:'Anfu Road · 安福路',q:'安福路',city:'上海'},{name:'Wukang Mansion · 武康大楼',q:'武康大楼',city:'上海'},{name:'Lục Gia Chủy · 陆家嘴',q:'陆家嘴滨江大道',city:'上海'},{name:'Tân Thiên Địa · 新天地',q:'上海新天地',city:'上海'},{name:'Hồ Thanh Sơn · 青山湖水上森林',q:'青山湖水上森林景区',city:'杭州'},{name:'Làng trà Long Tỉnh · 龙井村',q:'龙井村',city:'杭州'},{name:'Bảo tàng Trà · 中国茶叶博物馆',q:'中国茶叶博物馆 双峰馆',city:'杭州'},{name:'Phố Hà Phường · 河坊街',q:'河坊街',city:'杭州'},{name:'Bến Thượng Hải · 外滩',q:'外滩',city:'上海'},{name:'Dự Viên · 豫园',q:'豫园',city:'上海'},{name:'Phố Bình Giang · 平江路',q:'平江路',city:'苏州'},{name:'Chuyết Chính Viên · 拙政园',q:'拙政园',city:'苏州'},{name:'Tây Sách · 乌镇西栅',q:'乌镇西栅景区',city:'嘉兴'},{name:'Tây Hồ · 西湖',q:'西湖',city:'杭州'},{name:'Linh Ẩn Tự · 灵隐寺',q:'灵隐寺',city:'杭州'},{name:'Cung Yến Thượng Hải · 宫宴',q:'宫宴 北京西路1485号',city:'上海'},{name:'Ngự Yến Tô Châu · 吴宫御宴',q:'吴宫御宴 新市路259号',city:'苏州'},{name:'Cung Yến Hàng Châu · 杭州宫宴',q:'宫宴 曙光路122号',city:'杭州'},{name:'Ga Hàng Châu Đông · 杭州东站',q:'杭州东站',city:'杭州'},{name:'Ga Hongqiao · 上海虹桥站',q:'上海虹桥站',city:'上海'}];document.getElementById('quickMap').innerHTML=locations.map(l=>`<div class="map-stop"><div style="flex:1;font-size:12px;font-weight:760">${esc(l.name)}</div><a href="${amap(l.q,l.city)}" target="_blank" rel="noopener noreferrer">Mở bản đồ ↗</a></div>`).join('');}

function clampInt(n,min,max,def){n=Number(n);return Number.isFinite(n)?Math.min(max,Math.max(min,Math.round(n))):def}
function fmtCompact(n){return n>=1000?(Math.round(n/100)/10).toFixed(1).replace('.0','')+'k':formatCny(n)}
function selectedHotel(city){return hotels.find(h=>h.id===state.selectedHotels?.[city])||hotels.find(h=>h.city===city)}
function selectedHotelCost(){return cityHotels.reduce((r,c)=>{const h=selectedHotel(c.key);r.low+=h.low*c.nights;r.high+=h.high*c.nights;return r;},{low:0,high:0})}
function recommendVehicle(n,b){return vehicles.find(v=>v.pax>=n&&v.bags>=b)||null}
function hotelSectionCard(h,selected){return `<article class="hotel-card surface"><div class="hotel-top"><div><div class="hotel-nights">${h.nights} ĐÊM ${h.city==='sh'?'· NGÀY 1–2':''}</div><div class="hotel-badge">${esc(h.tag)}</div></div><span class="hotel-icon">⌂</span></div><div class="hotel-card-body"><h3>${esc(h.name)}</h3><div class="hotel-local">${esc(h.local)} · ${esc(h.area)}</div><p>${esc(h.blurb)}</p><div class="hotel-tips">💡 ${esc(h.tip)}</div><div class="hotel-bottom"><div class="hotel-price">${formatCny(h.low)}–${formatCny(h.high)} ¥<small>/ phòng / đêm · dự trù</small></div></div><div class="hotel-actions"><a href="${h.url}" target="_blank" rel="noopener noreferrer">Xem khách sạn ↗</a><a href="${amap(h.q,h.place)}" target="_blank" rel="noopener noreferrer">Amap ↗</a><button class="hotel-select ${selected?'selected':''}" data-hotel="${h.id}" type="button">${selected?'✓ Đã chọn':'Chọn khách sạn này'}</button></div></div></article>`}
function renderHotels(){
 const filter=document.getElementById('hotelOrder').value;
 document.getElementById('hotelCatalog').innerHTML=cityHotels.map(c=>{
 let list=hotels.filter(h=>h.city===c.key);
 if(c.key==='wz'&&filter==='inside')list=[...list].sort((a,b)=>(a.id==='wz-hampton')?1:(b.id==='wz-hampton')?-1:0);
 if(filter==='value')list=[...list].sort((a,b)=>a.low-b.low);
 return `<section class="hotel-city-group"><div class="hotel-city-title"><h2>${esc(c.name)}</h2><span>${esc(c.detail)} · ${Math.ceil(state.travelers/2)} phòng tham khảo</span></div><div class="hotel-grid">${list.map(h=>hotelSectionCard(h,selectedHotel(c.key).id===h.id)).join('')}</div></section>`}).join('');
 document.querySelectorAll('[data-hotel]').forEach(btn=>btn.addEventListener('click',()=>{
 const h=hotels.find(x=>x.id===btn.dataset.hotel);if(!h)return;
 state.selectedHotels[h.city]=h.id;save();renderHotels();renderDay();renderBudget();notify('Đã chọn '+h.name);
 }));
 const cost=selectedHotelCost(),rooms=Math.ceil(clampInt(state.travelers,1,40,10)/2);
 document.getElementById('hotelEstimate').textContent=`${formatCny(cost.low*rooms)}–${formatCny(cost.high*rooms)} ¥`;
 document.getElementById('hotelNightly').textContent=`6 đêm · ${rooms} phòng · giá dự trù`;
}
function stayPanelHTML(day){
 if(day===7)return `<div class="eyebrow">${icon('hotel',15)} KHÔNG NGỦ THÊM</div><h3>Ngày về</h3><p>6 đêm: Thượng Hải ×2, Tô Châu ×1, Ô Trấn ×1, Hàng Châu ×2.</p><div class="stay-box">Nếu chuyến bay về sớm, cân nhắc chuyển đêm 6 sang gần sân bay Thượng Hải; điều này sẽ thay đổi số đêm Hàng Châu trong dự toán.</div>`;
 const city=day<=2?'sh':day===3?'sz':day===4?'wz':'hz';const h=selectedHotel(city);
 return `<div class="eyebrow">${icon('hotel',15)} KHÁCH SẠN ĐÃ GỢI Ý · CHƯA ĐẶT</div><h3>${esc(h.name)}</h3><p>${esc(h.area)} · ${esc(h.local)}</p><div class="room-estimate">${formatCny(h.low)}–${formatCny(h.high)} CNY/phòng/đêm (dự trù)</div><div class="choice-line"><a href="${h.url}" target="_blank" rel="noopener noreferrer">Trang khách sạn ↗</a><a href="${amap(h.q,h.place)}" target="_blank" rel="noopener noreferrer">Mở Amap ↗</a></div><div class="stay-box"><b>Lưu ý đoàn:</b> ${esc(h.tip)}<br><button type="button" class="pill-button" onclick="show('hotels')" style="margin-top:10px">Đổi khách sạn ↗</button></div>`;
}
