 d7.stops[2]={t:'08:30',title:'Đi thẳng Hàng Châu → sân bay Thượng Hải',duration:'~3–4,5 giờ đến PVG (ước tính)',kind:'Di chuyển',detail:'Không ghé lại trung tâm Thượng Hải. Lịch xe phải được tính lùi từ giờ bay thực tế và có dự phòng tắc đường.',transport:'Xe thuê riêng; chọn sân bay PVG hoặc SHA đúng trên vé.',q:'上海浦东国际机场',city:'上海'};
 d7.stops[3]={t:'12:00+',title:'Đến sân bay, làm thủ tục quốc tế',duration:'Dành tối thiểu ~3 giờ trước giờ bay',kind:'Chính',detail:'Đây là mốc minh họa khi xe đi 08:30; không đảm bảo thời gian thực tế. Nếu giờ bay quá sớm, đổi lịch đêm 6 về Thượng Hải và tính lại chi phí khách sạn.',transport:'Xe đưa đến đúng terminal trên vé bay.',q:'上海浦东国际机场',city:'上海'};
