 d3.transport='Tàu cao tốc 上海虹桥 → 苏州站: thời gian trên tàu thường ~25–45 phút; cộng thời gian ra ga và chờ.';
 d3.stops[0]={t:'07:30',title:'Rời Thượng Hải đi Tô Châu',duration:'~25–45 phút trên tàu + ra ga',kind:'Di chuyển',detail:'Trả phòng, tới 上海虹桥站 trước giờ tàu đủ sớm.',transport:'Tàu cao tốc từ 上海虹桥 → 苏州站; giờ và vé cần đặt theo 12306.',q:'苏州站',city:'苏州'};
 d3.stops[1].t='10:00';
 d7.summary='Ngày cuối ưu tiên trả phòng, ra ga, đến sân bay Thượng Hải theo đúng giờ bay.';
